# ------------------------------------------------------------------------------
# Cell 4: Utility - text extraction for PDF/DOCX/TXT/MD

def extract_text_from_bytes(data: bytes, filename: str, mime: str) -> str:
    lower = filename.lower()
    if 'pdf' in lower or 'application/pdf' in mime:
        if have_pypdf:
            try:
                reader = pypdf.PdfReader(io.BytesIO(data))
                texts = []
                for p in reader.pages:
                    texts.append(p.extract_text() or '')
                return '\n'.join(texts)
            except Exception as e:
                print('pypdf failed:', e)
        # fallback naive: return empty or store raw bytes as base64
        print('PDF extraction not available; returning empty string')
        return ''
    if lower.endswith('.docx') or 'msword' in mime or lower.endswith('.doc'):
        if have_docx:
            try:
                from docx import Document
                doc = Document(io.BytesIO(data))
                return '\n'.join([p.text for p in doc.paragraphs])
            except Exception as e:
                print('python-docx failed:', e)
        print('DOCX extraction not available; returning empty string')
        return ''
    # text-like
    try:
        return data.decode('utf-8')
    except:
        try:
            return data.decode('latin-1')
        except:
            return ''

# ------------------------------------------------------------------------------
# Cell 5: Chunking function

def chunk_text(text: str, chunk_words: int = 400) -> List[str]:
    if not text:
        return []
    tokens = text.split()
    chunks = []
    for i in range(0, len(tokens), chunk_words):
        chunks.append(' '.join(tokens[i:i+chunk_words]))
    return chunks
